b app/helpers/proposals_dashboard_helper.rb app/helpers/admin/proposal_dashboard_actions_helper.rb app/graphql/types/proposal_type.rb app/graphql/types/proposal_notification_type.rb config/routes/proposal.rb app/assets/stylesheets/dashboard app/assets/stylesheets/dashboard.scss app/assets/stylesheets/dashboard_poster.scss app/assets/stylesheets/admin/dashboard app/assets/stylesheets/proposals app/assets/stylesheets/widgets/feeds/proposal.scss app/assets/javascripts/admin/dashboard app/assets/javascripts/dashboard_graphs.js'''.split()
