# Create a compact remaining runtime reference inventory (excluding legislation-only files)
python - <<'PY'
from pathlib import Path
import re
with open('/tmp/runtime','w') as out:
 for base in ['app','lib','config']:
  for p in Path(base).rglob('*'):
   if not p.is_file() or p.suffix not in ['.rb','.erb','.rake','.js','.scss'] or 'legislation' in p.parts: continue
   for i,l in enumerate(p.read_text().splitlines(),1):
    if re.search(r'proposal|Proposal|Dashboard::',l):out.write(f'{p}:{i}: {l}\n')
